    this.DTYPE = agfDType.UNSPECIFIED;
    this.FILL_VALUE = 0.0;
    this.SCALE_FACTOR = 1.0;
    this.ADD_OFFSET = 0.0;
    this.NX = 0;
    this.NY = 0;
    this.ROW_ORDER = agfRowOrder.UNSPECIFIED;
