static public class AGFVerify
{
  static public bool Verify(Google.FlatBuffers.Verifier verifier, uint tablePos)
  {
    return verifier.VerifyTableStart(tablePos)
      && verifier.VerifyString(tablePos, 4 /*ID*/, true)
      && verifier.VerifyString(tablePos, 6 /*EPOCH*/, true)
      && verifier.VerifyString(tablePos, 8 /*VALID_START*/, false)
      && verifier.VerifyString(tablePos, 10 /*VALID_END*/, false)
      && verifier.VerifyString(tablePos, 12 /*FORECAST_REFERENCE_TIME*/, false)
      && verifier.VerifyField(tablePos, 14 /*FORECAST_LEAD_S*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 16 /*VARIABLE*/, 1 /*agfVariable*/, 1, false)
      && verifier.VerifyString(tablePos, 18 /*UNITS*/, true)
      && verifier.VerifyVectorOfStrings(tablePos, 20 /*CATEGORY_LABELS*/, false)
      && verifier.VerifyField(tablePos, 22 /*DTYPE*/, 1 /*agfDType*/, 1, false)
      && verifier.VerifyField(tablePos, 24 /*FILL_VALUE*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 26 /*SCALE_FACTOR*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 28 /*ADD_OFFSET*/, 8 /*double*/, 8, false)
      && verifier.VerifyField(tablePos, 30 /*NX*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 32 /*NY*/, 4 /*uint*/, 4, false)
      && verifier.VerifyField(tablePos, 34 /*ROW_ORDER*/, 1 /*agfRowOrder*/, 1, false)
      && verifier.VerifyField(tablePos, 36 /*PROJECTION*/, 1 /*agfProjection*/, 1, false)
      && verifier.VerifyTable(tablePos, 38 /*PROJECTION_PARAMETERS*/, AGFProjectionParametersVerify.Verify, true)
      && verifier.VerifyField(tablePos, 40 /*PAYLOAD_CODEC*/, 1 /*agfPayloadCodec*/, 1, false)
      && verifier.VerifyVectorOfData(tablePos, 42 /*PAYLOAD*/, 1 /*byte*/, false)
      && verifier.VerifyString(tablePos, 44 /*PAYLOAD_CID*/, false)
      && verifier.VerifyString(tablePos, 46 /*PAYLOAD_SHA256*/, true)
      && verifier.VerifyField(tablePos, 48 /*PAYLOAD_SIZE_BYTES*/, 8 /*ulong*/, 8, false)
      && verifier.VerifyTable(tablePos, 50 /*PROVENANCE*/, AGFProvenanceVerify.Verify, true)
      && verifier.VerifyString(tablePos, 52 /*DESCRIPTION*/, false)
      && verifier.VerifyTableEnd(tablePos);
  }
}
